CREATE TABLE IF NOT EXISTS `dpn_medical_icu_episodes` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`admitted_by` varchar(64) NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),`ended_at` datetime NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `dpn_medical_icu_vitals` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`vitals` longtext NOT NULL,`triage` varchar(16) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_icu_vitals_cid` (`patient_cid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
